1	// hotloops -- hot inner-loop detector for baremetal RISC-V ELFs.
2	//
3	// C++ replacement for QEMU/scripts/hotloops.sh. Runs a baremetal ELF under
4	// qemu-system-{arch} with the hotloops TCG plugin and prints a sorted table
5	// (or LLM-ready Markdown report) of detected backward branches.
6	//
7	// Usage: hotloops [opts] <elf>
8	//
9	// Options:
10	//   --arch <riscv32|riscv64|auto>   Target arch (default: auto)
11	//   --qemu <path>                   Override qemu-system binary
12	//   --plugin <path>                 Override hotloops plugin .so
13	//   --machine <name>                -M <name> (default: andes_ae350)
14	//   --cpu <spec>                    -cpu <spec>
15	//   --qemu-config <file>            -readconfig <file>
16	//   --cwd <dir>                     chdir before launching QEMU
17	//   --qemu-arg <arg>                Extra arg forwarded to QEMU (repeatable)
18	//   --limit <N>                     Top-N loops to print (default: 50)
19	//   --min-iters <N>                 Drop loops with fewer than N iters (default: 1)
20	//   --objdump <path>                Override objdump
21	//   --addr2line <path>              Override addr2line
22	//   --no-source                     Disable source file:line resolution
23	//   --raw                           Print raw plugin log, no formatting
24	//   --optimize-rvv / --no-optimize-rvv  RVV-only filter (default: on)
25	//   --llm / --no-llm                LLM Markdown report vs. plain table (default: on)
