119	static Config parse_args(int argc, char** argv) {
120	  Config c;
121	  for (int i = 1; i < argc; ++i) {
122	    std::string a = argv[i];
123	    auto next = [&]() -> std::string {
124	      if (i + 1 >= argc) { fprintf(stderr, "error: %s requires an argument\n", argv[i]); exit(2); }
125	      return argv[++i];
126	    };
127	    if (a == "--arch")         c.arch         = next();
128	    else if (a == "--qemu")    c.qemu         = next();
129	    else if (a == "--plugin")  c.plugin       = next();
130	    else if (a == "--machine") c.machine      = next();
131	    else if (a == "--cpu")     c.cpu          = next();
132	    else if (a == "--qemu-config") c.qemu_config = next();
133	    else if (a == "--cwd")     c.qemu_cwd     = next();
134	    else if (a == "--qemu-arg") c.extra_qemu_args.push_back(next());
135	    else if (a == "--limit")   c.limit        = std::stoi(next());
136	    else if (a == "--min-iters") c.min_iters  = std::stoi(next());
137	    else if (a == "--objdump") c.objdump      = next();
138	    else if (a == "--addr2line") c.addr2line_bin = next();
139	    else if (a == "--no-source")    c.no_source    = true;
140	    else if (a == "--raw")          c.raw          = true;
141	    else if (a == "--optimize-rvv") c.optimize_rvv = true;
142	    else if (a == "--no-optimize-rvv") c.optimize_rvv = false;
143	    else if (a == "--llm")          c.llm          = true;
144	    else if (a == "--no-llm")       c.llm          = false;
145	    else if (a == "-h" || a == "--help") usage(argv[0]);
146	    else if (a.starts_with("-")) {
147	      fprintf(stderr, "error: unknown option: %s\n", a.c_str()); exit(2);
148	    } else {
149	      if (!c.elf.empty()) { fprintf(stderr, "error: unexpected positional arg: %s\n", a.c_str()); exit(2); }
150	      c.elf = a;
151	    }
152	  }
153	  if (c.elf.empty()) { fprintf(stderr, "error: ELF path required\n"); exit(2); }
154	  if (!fs::exists(c.elf)) { fprintf(stderr, "error: not found: %s\n", c.elf.c_str()); exit(2); }
155	  return c;
156	}
