291	static std::vector<LogEntry> parse_log(const std::string& path) {
292	  std::vector<LogEntry> rows;
293	  std::ifstream f(path);
294	  if (!f) return rows;
295	  static const std::regex re(R"(\s*(0x[0-9a-fA-F]+)\s*,\s*(0x[0-9a-fA-F]+)\s*,\s*(\d+))");
296	  std::string line;
297	  while (std::getline(f, line)) {
298	    std::smatch m;
299	    if (!std::regex_search(line, m, re)) continue;
300	    rows.push_back({
301	      std::stoull(m[1], nullptr, 16),
302	      std::stoull(m[2], nullptr, 16),
303	      std::stoull(m[3])
304	    });
305	  }
306	  return rows;
307	}
