420	static std::string src_basename(const std::string& s) {
421	  if (s.empty()) return "";
422	  // "path:line[ (extra)]" -> "basename(path):line[ ...]"
423	  auto sp = s.find(' ');
424	  std::string head = (sp != std::string::npos) ? s.substr(0, sp) : s;
425	  std::string tail = (sp != std::string::npos) ? s.substr(sp) : "";
426	  auto slash = head.rfind('/');
427	  return ((slash != std::string::npos) ? head.substr(slash + 1) : head) + tail;
428	}
