438	static std::string read_source_line(const std::string& path, int lineno) {
439	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
440	  std::ifstream f(path);
441	  std::string line;
442	  for (int i = 1; std::getline(f, line); ++i) {
443	    if (i == lineno) {
444	      while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
445	                                line.back() == ' '  || line.back() == '\t'))
446	        line.pop_back();
447	      auto s = line.find_first_not_of(" \t");
448	      return (s != std::string::npos) ? line.substr(s) : line;
449	    }
450	  }
451	  return "";
452	}
