503	static void print_table(
504	    const std::vector<LogEntry>& rows,
505	    const std::string& elf_path,
506	    const std::map<uint64_t, std::string>& src_map,
507	    int min_iters, bool optimize_rvv)
508	{
509	  bool have_src = !src_map.empty();
510	
511	  auto srcpair = [&](uint64_t s, uint64_t e) -> std::string {
512	    std::string a = src_short(src_map, s), b = src_short(src_map, e);
513	    if (!a.empty() && a == b) return a;
514	    return (a.empty() ? "?" : a) + " -> " + (b.empty() ? "?" : b);
515	  };
516	
517	  printf("# hot loops (iters >= %d", min_iters);
518	  if (optimize_rvv) printf(", RVV-only");
519	  printf("), sorted desc, top %zu\n", rows.size());
520	
521	  size_t w_iter = 5;  // strlen("iters")
522	  for (const auto& r : rows) {
523	    char buf[24]; snprintf(buf, sizeof(buf), "%llu", (unsigned long long)r.iters);
524	    w_iter = std::max(w_iter, strlen(buf));
525	  }
526	  const size_t w_pc = 18;
527	  size_t w_sym = 8;  // strlen("location")
528	  for (const auto& r : rows) {
529	    std::string loc = sym_at(elf_path, r.start) + " -> " + sym_at(elf_path, r.end);
530	    w_sym = std::max(w_sym, loc.size());
531	  }
532	
533	  if (have_src) {
534	    printf("%*s | %-*s -> %-*s | %-*s | source\n",
535	           static_cast<int>(w_iter), "iters",
536	           static_cast<int>(w_pc), "start_pc",
537	           static_cast<int>(w_pc), "end_pc",
538	           static_cast<int>(w_sym), "location");
539	  } else {
540	    printf("%*s | %-*s -> %-*s | location\n",
541	           static_cast<int>(w_iter), "iters",
542	           static_cast<int>(w_pc), "start_pc",
543	           static_cast<int>(w_pc), "end_pc");
544	  }
545	  size_t sep = w_iter + 3 + w_pc + 4 + w_pc + 3 + w_sym;
546	  if (have_src) sep += 3 + 12;
547	  printf("%s\n", std::string(sep, '-').c_str());
548	
549	  for (const auto& r : rows) {
550	    std::string loc = sym_at(elf_path, r.start) + " -> " + sym_at(elf_path, r.end);
551	    if (have_src)
552	      printf("%*llu | 0x%016llx -> 0x%016llx | %-*s | %s\n",
553	             static_cast<int>(w_iter), (unsigned long long)r.iters,
554	             (unsigned long long)r.start, (unsigned long long)r.end,
555	             static_cast<int>(w_sym), loc.c_str(),
556	             srcpair(r.start, r.end).c_str());
557	    else
558	      printf("%*llu | 0x%016llx -> 0x%016llx | %s\n",
559	             static_cast<int>(w_iter), (unsigned long long)r.iters,
560	             (unsigned long long)r.start, (unsigned long long)r.end,
561	             loc.c_str());
562	  }
563	}
