594	        if (i) rvv_str += ", ";
595	        rvv_str += uniq[i];
596	      }
597	      if (uniq.size() > 3) { rvv_str += ", +" + std::to_string(uniq.size()-3) + " more"; }
598	      rvv_str += ")";
599	    } else {
600	      rvv_str = "scalar";
601	    }
